#include <deque>

using namespace std;

class FrontMiddleBackQueue {
    deque<int> front, back;

    void balance() {
        if (front.size() > back.size()) {
            back.push_front(front.back());
            front.pop_back();
        } else if (back.size() > front.size() + 1) {
            front.push_back(back.front());
            back.pop_front();
        }
    }

public:
    void pushFront(int val) {
        front.push_front(val);
        balance();
    }

    void pushMiddle(int val) {
        if (front.size() < back.size())
            front.push_back(val);
        else
            back.push_front(val);
    }

    void pushBack(int val) {
        back.push_back(val);
        balance();
    }

    int popFront() {
        if (front.empty() && back.empty()) return -1;
        int val;
        if (!front.empty()) {
            val = front.front();
            front.pop_front();
        } else {
            val = back.front();
            back.pop_front();
        }
        balance();
        return val;
    }

    int popMiddle() {
        if (front.empty() && back.empty()) return -1;
        int val;
        if (front.size() == back.size()) {
            val = front.back();
            front.pop_back();
        } else {
            val = back.front();
            back.pop_front();
        }
        return val;
    }

    int popBack() {
        if (front.empty() && back.empty()) return -1;
        int val = back.back();
        back.pop_back();
        balance();
        return val;
    }
};
